class Solution {
public:
    int minSessions(vector<int>& tasks, int sessionTime) {
        int n = (int)tasks.size();
        int full = 1 << n;
        const int INF = 1e9;
        // dp[mask] = {minSessions, maxRemainingInLastSession}
        vector<pair<int,int>> dp(full, {INF, 0});
        dp[0] = {0, 0};
        for (int mask = 0; mask < full; mask++) {
            int sess = dp[mask].first;
            if (sess == INF) continue;
            int rem = dp[mask].second;
            for (int i = 0; i < n; i++) {
                if (mask & (1 << i)) continue;
                int nmask = mask | (1 << i);
                int nsess, nrem;
                if (rem >= tasks[i]) {
                    nsess = sess;
                    nrem = rem - tasks[i];
                } else {
                    nsess = sess + 1;
                    nrem = sessionTime - tasks[i];
                }
                if (nsess < dp[nmask].first ||
                    (nsess == dp[nmask].first && nrem > dp[nmask].second)) {
                    dp[nmask] = {nsess, nrem};
                }
            }
        }
        return dp[full - 1].first;
    }
};
